INSERT INTO results (id, tag, type, title, statement_tex, statement_html_cache, section_id, position, visibility, listed, revision, created_at, updated_at, created_by, updated_by) VALUES (122, '8JS9', 'example', 'The smoothed prime sum of the trivial character', 'Take $\chi = \mathbf 1$ in the \hyperref[8JF7]{definition of the smoothed prime sum}, so that
\[ R_{\mathbf 1}(x) = \sum_{n \le x} \Lambda(n)\Bigl(\frac xn - 1\Bigr), \qquad M_{\mathbf 1}(x) = x\log x - (1+\gamma)x, \qquad G_{\mathbf 1}(x) = R_{\mathbf 1}(x) - M_{\mathbf 1}(x), \]
where $M_{\mathbf 1}$ is the main term of \ref{8JS3}. Panel (a) shows $R_{\mathbf 1}$ and $M_{\mathbf 1}$ for $1 \le x \le 50$; panel (b) shows $G_{\mathbf 1}$ for $1 \le x \le 1000$, with a dashed line at $\log 2\pi \approx 1.838$.
\includegraphics[width=1, alt=Graphs of R_1 and M_1 for x up to 50 and of G_1 for x up to 1000]{/static/figures/smoothed-prime-sum-trivial.svg}
Some values:
\[ \begin{array}{r|rrr} x & R_{\mathbf 1}(x) & M_{\mathbf 1}(x) & G_{\mathbf 1}(x) \\ \hline 10 & 9.114 & 7.254 & 1.861 \\ 100 & 304.517 & 302.795 & 1.722 \\ 1000 & 5332.071 & 5330.540 & 1.531 \\ 10000 & 76332.996 & 76331.247 & 1.749 \end{array} \]
So $R_{\mathbf 1}(x)$ grows like $x\log x$, while $1.41 < G_{\mathbf 1}(x) < 2.21$ for $1 \le x \le 1000$.', NULL, 102, 3, 'published', 1, 1, '2026-11-24 13:00:00', '2026-11-24 13:00:00', 'claude', 'claude');
